function getCellCenter(points, i, j) {
  var cellCenterX = (points[i][j].x + points[i + 1][j].x + points[i + 1][j + 1].x + points[i][j + 1].x) / 4;
  var cellCenterY = (points[i][j].y + points[i + 1][j].y + points[i + 1][j + 1].y + points[i][j + 1].y) / 4;
  return createVector(cellCenterX, cellCenterY);
}

class RumoreND {
  constructor(dimensions) {
    this.dimensions = dimensions; // Numero di dimensioni
    this.permutation = [];
    this.gradients = [];
    this.initialize();
  }

  initialize() {
    // Genera una permutazione casuale degli indici
    this.permutation = Array.from({ length: 256 }, (_, i) => i);
    for (let i = this.permutation.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      [this.permutation[i], this.permutation[j]] = [this.permutation[j], this.permutation[i]];
    }
    this.permutation = this.permutation.concat(this.permutation);

    // Genera gradienti casuali
    this.gradients = Array.from({ length: 256 }, () => {
      // Vettore unitario casuale n-dimensionale
      const vec = Array.from({ length: this.dimensions }, () => random(-1, 1));
      const mag = Math.sqrt(vec.reduce((sum, v) => sum + v * v, 0));
      return vec.map(v => v / mag); // Normalizza
    });
  }

  dotGridGradient(gridCoords, pointCoords) {
    // Calcola il prodotto scalare tra il gradiente e il vettore differenza
    const index = gridCoords.reduce((sum, coord, dim) => {
      return this.permutation[(sum + coord) % 256];
    }, 0);
    const gradient = this.gradients[index % 256];

    return pointCoords.reduce((dot, point, dim) => {
      return dot + (point - gridCoords[dim]) * gradient[dim];
    }, 0);
  }

  fade(t) {
    // Funzione di interpolazione per rendere il movimento fluido
    return t * t * t * (t * (t * 6 - 15) + 10);
  }

  lerp(a, b, t) {
    // Interpolazione lineare
    return a + t * (b - a);
  }

  noise(...coords) {
    if (coords.length !== this.dimensions) {
      throw new Error(`Il numero di coordinate deve essere ${this.dimensions}`);
    }

    // Determina i nodi della griglia
    const gridCoords0 = coords.map(coord => Math.floor(coord));
    const gridCoords1 = gridCoords0.map(coord => coord + 1);

    // Ricorsione per calcolare il rumore in tutte le dimensioni
    const interpolate = (dim, grid0, grid1) => {
      if (dim === this.dimensions) {
        return this.dotGridGradient(grid0, coords);
      }

      const fadeT = this.fade(coords[dim] - grid0[dim]);
      const g0 = interpolate(dim + 1, grid0, [...grid1.slice(0, dim), grid0[dim], ...grid1.slice(dim + 1)]);
      const g1 = interpolate(dim + 1, grid0, [...grid1.slice(0, dim), grid1[dim], ...grid1.slice(dim + 1)]);
      return this.lerp(g0, g1, fadeT);
    };

    return interpolate(0, gridCoords0, gridCoords1);
  }
}

function fBM(x, y, octaves, lacunarity, gain) {
  let amplitude = 1;
  let frequency = 1;
  let value = 0;

  for (let i = 0; i < octaves; i++) {
    value += amplitude * noise(x * frequency, y * frequency);
    amplitude *= gain;       // Riduce l'ampiezza
    frequency *= lacunarity; // Aumenta la frequenza
  }

  return value;
}

function granulate(amount) {
 // Apply grain effect
  loadPixels();
  const d = pixelDensity();
  const pixelsCount = 4 * (width * d) * (height * d);

  for (let i = 0; i < pixelsCount; i += 4) {
    var x = (i / 4) % (width * d);
    var y = floor((i / 4) / (width * d));
    let noiseVal = noise(x * 0.005/pD, y * 0.005/pD);
    let grainAmount = map(noiseVal, 0, 1, -amount, amount);

    pixels[i] += grainAmount;     // Red
    pixels[i + 1] += grainAmount; // Green
    pixels[i + 2] += grainAmount; // Blue
  }
  updatePixels();
}


