function grigliaB1(x, y) {
  // Calcolo della curvatura gaussiana K
  var z = 1 / (2 * a) * log(x * x + y * y);
  let expTerm = exp(2 * z / a);
  let K = -(a * a) / ((a * a + expTerm) ** 2);

  // Restituisci il punto calcolato con curvatura
  return { x: x, y: y, z: z, K: K };
}

